let catalog=null,adminData=null,adminTab='overview';
const dateLocal=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'America/Bahia'});
async function requestAPI(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível conectar.');return data}
function errorNotice(error){toast(error.message||'Falha na conexão. Tente novamente.')}
function renderCatalog(){document.querySelector('#services').innerHTML=catalog.services.map((s,i)=>`<article class="card"><div role="img" aria-label="${esc(s.name)}" class="crop" style="--pos:${[3.1,11.4,20,28.5,37,45.5][s.image%6]}% 52.4%"></div><h3>${esc(s.name.toUpperCase())}</h3><div class="price">${money(s.price)}<small>◷ ${s.duration} min</small></div><button class="gold" onclick="book(${i})">AGENDAR</button></article>`).join('');document.querySelector('#products').innerHTML=catalog.products.map((p,i)=>`<article class="card product"><div role="img" aria-label="${esc(p.name)}" class="crop" style="--pos:${[27.2,32.8,38.4,44,49.6,55.2][p.image%6]}% 77.8%"></div><h3>${esc(p.name)}</h3><div class="price">${money(p.price)}</div><button class="outline" onclick="add(${i})">ADICIONAR</button></article>`).join('');document.querySelectorAll('[data-contact]').forEach(a=>a.href='https://wa.me/'+catalog.settings.phone);const address=document.querySelector('#business-address');if(address)address.textContent=catalog.settings.address||'Consulte a localização pelo WhatsApp';}
async function init(){try{catalog=await requestAPI('bootstrap');renderCatalog();if(location.hash.startsWith('#admin')||location.pathname==='/admin')dashboard()}catch(e){errorNotice(e)}}
book=async function(index=0){if(!catalog){errorNotice(new Error('Carregando serviços. Tente novamente.'));return}if(!Number.isInteger(index)||!catalog.services[index])throw Error('Serviço inválido');show(`<div class="modal-kicker">BARBER PRIME · AGENDAMENTO</div><h2>Reserve seu momento.</h2><p class="notice">Escolha o serviço, o profissional e um horário disponível.</p><form id="booking"><div class="form-grid"><div><label for="service">Serviço</label><select id="service">${catalog.services.map((s,i)=>`<option value="${s.id}" ${index===i?'selected':''}>${esc(s.name)} · ${money(s.price)}</option>`).join('')}</select></div><div><label for="barber">Profissional</label><select id="barber">${catalog.barbers.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div><label for="date">Data</label><input id="date" type="date" min="${dateLocal()}" value="${dateLocal()}" required></div><div><label for="time">Horário disponível</label><select id="time" required></select></div><div><label for="name">Nome completo</label><input id="name" required minlength="2" maxlength="80" autocomplete="name"></div><div><label for="phone">Celular com DDD</label><input id="phone" type="tel" required inputmode="tel" autocomplete="tel" placeholder="(77) 98138-8366" maxlength="20"><small class="field-help">Usaremos este número para falar sobre a reserva.</small></div></div><label for="notes">Observações <small>(opcional)</small></label><textarea id="notes" maxlength="500" placeholder="Conte sua preferência de corte"></textarea><label class="check"><input id="consent" type="checkbox">Quero receber confirmação e lembrete deste agendamento pelo WhatsApp.</label><p class="notice">O atendimento confirmará sua reserva. Lembretes são enviados pela equipe; automação ainda não ativada.</p><div id="booking-error" role="alert" class="form-error"></div><button class="gold" type="submit">SOLICITAR AGENDAMENTO</button></form>`);
 const form=document.querySelector('#booking');let seq=0;const availability=async()=>{const ticket=++seq,select=document.querySelector('#time');select.innerHTML='<option value="">Carregando…</option>';try{const day=document.querySelector('#date').value,barber=document.querySelector('#barber').value,service=catalog.services.find(x=>x.id===document.querySelector('#service').value);const {busy}=await requestAPI('availability?day='+day+'&barber='+barber);if(ticket!==seq||!document.querySelector('#time'))return;const times=[];for(let m=catalog.settings.open*60;m+service.duration<=catalog.settings.close*60;m+=15){let free=true;for(let n=m;n<m+service.duration;n+=5)if(busy.includes(n))free=false;const t=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');if(new Date(day+'T'+t+':00-03:00')<=new Date())free=false;if(free)times.push(t)}select.innerHTML=times.length?times.map(t=>`<option>${t}</option>`).join(''):'<option value="">Sem horários nesta data</option>'}catch(e){if(ticket===seq)select.innerHTML='<option value="">Não foi possível carregar</option>';errorNotice(e)}};
 ['date','barber','service'].forEach(id=>document.getElementById(id).onchange=availability);await availability();form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]'),get=id=>document.getElementById(id).value;button.disabled=true;try{let phone=get('phone').replace(/\D/g,'');if(phone.length===11)phone='55'+phone;if(!/^55[1-9]{2}9\d{8}$/.test(phone))throw Error('Digite um celular válido com DDD, como (77) 98138-8366.');const saved=await requestAPI('bookings',{service:get('service'),barber:get('barber'),date:get('date'),time:get('time'),name:get('name'),phone,consent:document.querySelector('#consent').checked,notes:get('notes')});show(`<div class="success-icon">✓</div><h2>Solicitação registrada.</h2><p>${saved.date.split('-').reverse().join('/')} às ${saved.time}</p><p class="notice">Status: aguardando confirmação da barbearia. Seu telefone foi salvo com a reserva.</p><button class="gold" onclick="modal.close()">CONCLUIR</button>`);if(adminData)loadAdmin()}catch(e){document.querySelector('#booking-error').textContent=e.message;button.disabled=false}};
};
add=function(i){cart.push(i);document.querySelector('#count').textContent=cart.length;toast('Produto adicionado ao carrinho')};
showCart=function(){show(`<h2>SEU CARRINHO</h2>${cart.length?cart.map((id,i)=>`<div class="cart-row"><span>${esc(catalog.products[id].name)}</span><strong>${money(catalog.products[id].price)}</strong><button onclick="remove(${i})" aria-label="Remover produto">×</button></div>`).join('')+`<h3>Total: ${money(cart.reduce((s,i)=>s+catalog.products[i].price,0))}</h3><p class="notice">Consulte disponibilidade, pagamento e retirada com a barbearia.</p><a class="gold" href="https://wa.me/${catalog.settings.phone}?text=${encodeURIComponent('Olá! Tenho interesse em: '+cart.map(i=>catalog.products[i].name).join(', '))}" target="_blank" rel="noopener">CONSULTAR PELO WHATSAPP</a>`:'<p>Seu carrinho está vazio.</p>'}`)};
const menu=[['overview','◈','Visão geral'],['bookings','▦','Agendamentos'],['clients','♙','Clientes'],['barbers','✂','Profissionais'],['services','◇','Serviços'],['products','▣','Produtos e estoque'],['finance','▤','Financeiro'],['reminders','◉','WhatsApp'],['settings','⚙','Configurações']];
dashboard=async function(){modal.close();document.body.classList.add('admin-mode');document.getElementById('admin-app').hidden=false;location.hash='admin';document.getElementById('admin-app').innerHTML=`<aside class="admin-sidebar"><a class="logo" onclick="exitAdmin()"><span>♛</span>BARBER<small>— PRIME —</small></a><p class="side-caption">GESTÃO DA BARBEARIA</p><nav>${menu.map(m=>`<button data-tab="${m[0]}" onclick="switchTab('${m[0]}')"><span>${m[1]}</span>${m[2]}</button>`).join('')}</nav><div class="side-bottom"><span class="pill">ACESSO DO PROPRIETÁRIO</span><button class="outline" onclick="exitAdmin()">← Voltar ao site</button></div></aside><div class="admin-main"><div class="admin-top"><button class="text-button" onclick="exitAdmin()">← Site</button><div><button class="outline" onclick="loadAdmin()">↻ Atualizar</button><button class="gold" onclick="book()">+ Agendamento</button></div></div><div id="admin-content"><p class="notice">Carregando seus dados…</p></div></div>`;await loadAdmin()};
function exitAdmin(){document.body.classList.remove('admin-mode');document.querySelector('#admin-app').hidden=true;history.replaceState(null,'','/#inicio');init()}
async function loadAdmin(){try{adminData=await requestAPI('admin');switchTab(adminTab)}catch(e){document.querySelector('#admin-content').innerHTML=`<h1>Acesso protegido</h1><p class="notice">${esc(e.message)}</p><a class="gold" href="/signin-with-chatgpt?return_to=%2F%23admin" target="_top">ENTRAR COM CHATGPT</a>`}}
function stat(label,value,detail){return `<article class="metric"><span>${label}</span><strong>${value}</strong><small>${detail}</small></article>`}
function empty(text){return `<div class="empty-state"><span>◇</span><h3>${text}</h3><p>Os novos registros aparecerão aqui.</p></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>${rows.length?'':empty('Nenhum registro encontrado')}</div>`}
function total(rows,key){return rows.reduce((n,r)=>n+Number(r[key]||0),0)}
function statusOptions(b){return `<select aria-label="Status do agendamento de ${esc(b.name)}" class="status-select" onchange="changeStatus('${b.id}',this.value)">${['Pendente','Confirmado','Concluído','Cancelado','Não compareceu'].map(s=>`<option ${b.status===s?'selected':''}>${s}</option>`).join('')}</select>`}
function bookingTable(rows){return table(['Data e horário','Cliente','Serviço / profissional','Valor','Status','Contato'],rows.map(b=>`<tr><td><strong>${b.date.split('-').reverse().join('/')}</strong><br><small>${b.time} · ${b.duration} min</small></td><td><strong>${esc(b.name)}</strong><br><small>${esc(b.phone)}</small>${b.notes?`<details><summary>Observações</summary>${esc(b.notes)}</details>`:''}</td><td>${esc(b.serviceName)}<br><small>${esc(b.barberName)}</small></td><td>${money(b.price)}</td><td>${statusOptions(b)}</td><td><button class="text-button" onclick="reminder('${b.id}')">WhatsApp ↗</button></td></tr>`))}
function clients(){const map=new Map;for(const b of adminData.bookings){if(!map.has(b.phone))map.set(b.phone,{name:b.name,phone:b.phone,visits:0,spent:0,last:b.date,consent:b.consent});const c=map.get(b.phone);if(b.status==='Concluído'){c.visits++;c.spent+=b.price}if(b.date>c.last)c.last=b.date}return [...map.values()]}
function switchTab(tab){adminTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const el=document.querySelector('#admin-content');const today=dateLocal(),month=today.slice(0,7),done=adminData.bookings.filter(b=>b.status==='Concluído'&&b.date.startsWith(month)),expenses=adminData.expenses.filter(x=>x.date.startsWith(month)),revenue=total(done,'price'),commission=done.reduce((n,b)=>n+b.price*b.commission/100,0);const title=menu.find(m=>m[0]===tab)[2];let content='';
 if(tab==='overview'){const upcoming=adminData.bookings.filter(b=>b.date>=today&&!['Cancelado','Não compareceu','Concluído'].includes(b.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));content=`<div class="metrics">${stat('Agendamentos hoje',adminData.bookings.filter(b=>b.date===today&&b.status!=='Cancelado').length,'Reservas registradas')}${stat('Receita do mês',money(revenue),'Serviços concluídos')}${stat('Clientes',clients().length,'Identificados pelo telefone')}${stat('A confirmar',upcoming.filter(b=>b.status==='Pendente').length,'Próximos atendimentos')}</div><div class="panel"><div class="panel-title"><h2>Próximos agendamentos</h2><button class="text-button" onclick="switchTab('bookings')">Ver agenda →</button></div>${bookingTable(upcoming.slice(0,8))}</div><div class="admin-grid"><div class="panel"><h2>Receita nos últimos 7 dias</h2>${revenueChart()}</div><div class="panel"><h2>Atenção na operação</h2><div class="insight"><strong>${adminData.products.filter(p=>p.stock<=3).length}</strong> produtos com estoque baixo</div><div class="insight"><strong>${upcoming.filter(b=>b.consent).length}</strong> reservas com autorização de lembrete</div><p class="notice">WhatsApp automático: não conectado. Prepare as mensagens na aba WhatsApp.</p></div></div>`}
 if(tab==='bookings')content=`<div class="toolbar"><input id="booking-search" placeholder="Buscar cliente, telefone ou serviço" oninput="filterBookings()"><input id="booking-date" aria-label="Filtrar por data" type="date" onchange="filterBookings()"><select id="booking-status" aria-label="Filtrar por status" onchange="filterBookings()"><option value="">Todos os status</option>${['Pendente','Confirmado','Concluído','Cancelado','Não compareceu'].map(s=>`<option>${s}</option>`).join('')}</select><button class="outline" onclick="exportData('bookings')">Exportar CSV</button></div><div class="panel" id="booking-results">${bookingTable([...adminData.bookings].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))}</div>`;
 if(tab==='clients')content=`<div class="toolbar"><p class="notice">Histórico agrupado pelo celular informado no agendamento.</p><button class="outline" onclick="exportData('clients')">Exportar CSV</button></div><div class="panel">${table(['Cliente','WhatsApp','Visitas concluídas','Total em serviços','Última reserva'],clients().map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone)}</td><td>${c.visits}</td><td>${money(c.spent)}</td><td>${c.last.split('-').reverse().join('/')}</td></tr>`))}</div>`;
 if(['services','barbers','products'].includes(tab)){const names={services:'serviço',barbers:'profissional',products:'produto'};content=`<div class="toolbar"><p class="notice">Cadastros atualizam a agenda e a vitrine do site.</p><button class="gold" onclick="editRecord('${tab}')">+ Novo ${names[tab]}</button></div><div class="panel">${table(tab==='services'?['Serviço','Preço','Duração','Situação','Ações']:tab==='barbers'?['Profissional','Comissão','Atendimentos concluídos','Situação','Ações']:['Produto','Preço','Estoque','Situação','Ações'],adminData[tab].map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${tab==='barbers'?r.commission+'%':money(r.price)}</td><td>${tab==='services'?r.duration+' min':tab==='products'?`<span class="pill ${r.stock<=3?'warning':''}">${r.stock} unidades</span>`:adminData.bookings.filter(b=>b.barber===r.id&&b.status==='Concluído').length}</td><td>${r.active?'Ativo':'Inativo'}</td><td><button class="text-button" onclick="editRecord('${tab}','${r.id}')">Editar</button></td></tr>`))}</div>`}
 if(tab==='finance')content=`<div class="metrics">${stat('Receita · '+month,money(revenue),'Serviços concluídos')}${stat('Comissões',money(commission),'Percentual na data da reserva')}${stat('Despesas',money(total(expenses,'amount')),'Lançamentos do mês')}${stat('Resultado operacional',money(revenue-commission-total(expenses,'amount')),'Receita − comissões − despesas')}</div><div class="toolbar"><p class="notice">Receita de serviços; vendas de produtos e pagamentos online não estão integrados.</p><button class="gold" onclick="editRecord('expenses')">+ Despesa</button><button class="outline" onclick="exportData('expenses')">Exportar</button></div><div class="panel"><h2>Despesas</h2>${table(['Descrição','Categoria','Data','Valor','Ações'],adminData.expenses.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.category)}</td><td>${r.date.split('-').reverse().join('/')}</td><td>${money(r.amount)}</td><td><button class="text-button" onclick="editRecord('expenses','${r.id}')">Editar</button></td></tr>`))}</div>`;
 if(tab==='reminders'){const eligible=adminData.bookings.filter(b=>b.date>=today&&b.consent&&['Pendente','Confirmado'].includes(b.status));content=`<div class="connection-card"><span class="connection-icon">◉</span><div><h2>WhatsApp da barbearia</h2><p>+${esc(catalog.settings.phone)}</p><span class="pill warning">Envio manual disponível · Automação não conectada</span></div></div><div class="panel"><h2>Lembretes autorizados</h2><p class="notice">Confira a mensagem antes de abrir o WhatsApp. Abrir a conversa não significa que a mensagem foi enviada.</p>${table(['Cliente','Agendamento','Serviço','Ação'],eligible.map(b=>`<tr><td>${esc(b.name)}<br><small>${esc(b.phone)}</small></td><td>${b.date.split('-').reverse().join('/')} às ${b.time}</td><td>${esc(b.serviceName)}</td><td><button class="gold" onclick="reminder('${b.id}')">Preparar lembrete</button></td></tr>`))}</div><div class="panel"><h2>Para ativar o envio automático</h2><p class="notice">É necessário conectar uma conta WhatsApp Business Platform, configurar um modelo de mensagem aprovado e um serviço de execução agendada. Credenciais devem ficar no servidor. Não informe tokens neste painel.</p></div>`}
 if(tab==='settings'){const s=adminData.settings[0];content=`<div class="panel settings-panel"><h2>Dados da barbearia</h2><form id="settings-form"><div class="form-grid">${field('name','Nome',s.name)}${field('phone','WhatsApp comercial',s.phone,'tel')}${field('address','Endereço',s.address)}${field('open','Abertura (hora)',s.open,'number')}${field('close','Fechamento (hora)',s.close,'number')}${field('reminderHours','Antecedência desejada do lembrete (horas)',s.reminderHours,'number')}</div><p class="notice">A antecedência fica salva para a futura integração automática. Hoje, o envio é manual.</p><div class="form-error" id="settings-error"></div><button class="gold">SALVAR CONFIGURAÇÕES</button></form></div><div class="panel"><h2>Acesso e dados</h2><p class="notice">Na versão online, o painel exige a conta do proprietário autorizada no servidor. Nesta prévia local, o acesso ocorre neste computador. Os cadastros e agendamentos ficam no banco de dados.</p></div>`}
 el.innerHTML=`<div class="admin-heading"><div><p>BARBER PRIME</p><h1>${title}</h1></div><span>${new Date().toLocaleDateString('pt-BR',{dateStyle:'long'})}</span></div>${content}`;
 if(tab==='settings')document.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();const item=Object.fromEntries(new FormData(e.target));try{await requestAPI('admin/save',{kind:'settings',item});await loadAdmin();await init();toast('Configurações salvas')}catch(e){document.querySelector('#settings-error').textContent=e.message}};
}
function field(name,label,value='',type='text'){return `<div><label for="edit-${name}">${label}</label><input id="edit-${name}" name="${name}" type="${type}" value="${esc(String(value??''))}" ${type==='number'?'min="0" step="any"':''} ${name==='address'?'':'required'}></div>`}
function editRecord(kind,id){const item=adminData[kind].find(x=>x.id===id)||{active:true,price:0,duration:30,commission:40,stock:0,date:dateLocal(),amount:0};show(`<h2>${id?'Editar':'Novo'} cadastro</h2><form id="edit-form"><div class="form-grid">${field('name','Nome / descrição',item.name)}${['services','products'].includes(kind)?field('price','Preço (R$)',item.price,'number'):''}${kind==='services'?field('duration','Duração (minutos)',item.duration,'number'):''}${kind==='barbers'?field('commission','Comissão (%)',item.commission,'number'):''}${kind==='products'?field('stock','Estoque (unidades)',item.stock,'number'):''}${kind==='expenses'?field('amount','Valor (R$)',item.amount,'number')+field('date','Data',item.date,'date')+field('category','Categoria',item.category||'Operação'):''}</div>${kind!=='expenses'?`<label class="check"><input id="edit-active" type="checkbox" ${item.active?'checked':''}>Cadastro ativo</label>`:''}<div class="form-error" id="edit-error"></div><button class="gold" type="submit">SALVAR</button></form>`);document.querySelector('#edit-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await requestAPI('admin/save',{kind,item:{...item,...Object.fromEntries(new FormData(e.target)),id,active:document.querySelector('#edit-active')?.checked??true}});modal.close();await loadAdmin();catalog=await requestAPI('bootstrap');renderCatalog();toast('Cadastro salvo')}catch(e){document.querySelector('#edit-error').textContent=e.message;button.disabled=false}}}
async function changeStatus(id,status){try{await requestAPI('admin/status',{id,status});await loadAdmin();toast('Status atualizado')}catch(e){errorNotice(e);await loadAdmin()}}
function filterBookings(){const query=document.querySelector('#booking-search').value.toLowerCase(),day=document.querySelector('#booking-date').value,status=document.querySelector('#booking-status').value;document.querySelector('#booking-results').innerHTML=bookingTable(adminData.bookings.filter(b=>(!day||b.date===day)&&(!status||b.status===status)&&[b.name,b.phone,b.serviceName].join(' ').toLowerCase().includes(query)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))}
function reminder(id){const b=adminData.bookings.find(x=>x.id===id);if(!b.consent){show('<h2>Lembrete não autorizado</h2><p>Este cliente não marcou a autorização para lembretes no WhatsApp.</p>');return}const text=`Olá, ${b.name}! Aqui é da ${catalog.settings.name}. Lembramos do seu agendamento de ${b.serviceName} com ${b.barberName}, dia ${b.date.split('-').reverse().join('/')} às ${b.time}. Pode confirmar sua presença?`;show(`<h2>Preparar lembrete</h2><p class="notice">Destinatário: ${esc(b.phone)}</p><div class="message-preview">${esc(text)}</div><p class="notice">A mensagem será aberta para você revisar e enviar no WhatsApp.</p><a class="gold" href="https://wa.me/${b.phone}?text=${encodeURIComponent(text)}" target="_blank" rel="noopener">ABRIR WHATSAPP</a>`)}
function revenueChart(){const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toLocaleDateString('sv-SE',{timeZone:'America/Bahia'});days.push({day:key.slice(8)+'/'+key.slice(5,7),value:total(adminData.bookings.filter(b=>b.date===key&&b.status==='Concluído'),'price')})}const max=Math.max(1,...days.map(d=>d.value));return `<div class="revenue-chart">${days.map(d=>`<div><small>${money(d.value)}</small><span style="height:${Math.max(2,d.value/max*130)}px"></span><small>${d.day}</small></div>`).join('')}</div>`}
function exportData(kind){const data=kind==='clients'?clients():adminData[kind];if(!data.length){toast('Não há registros para exportar');return}const keys=Object.keys(data[0]),cell=v=>'"'+String(v??'').replace(/^[=+@-]/,'\t$&').replace(/"/g,'""')+'"',csv='\uFEFF'+[keys.join(';'),...data.map(r=>keys.map(k=>cell(r[k])).join(';'))].join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='barber-prime-'+kind+'-'+dateLocal()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#admin')&&document.body.classList.contains('admin-mode'))exitAdmin()});init();



